extracted_python_code:
customer_success_rates = Customers.WHERE(
    COUNT(transactions_made) >= 5
).CALCULATE(
    customer_name=name,
    success_rate=(COUNT(transactions_made.WHERE(status == 'completed')) / COUNT(transactions_made)) * 100.0
).ORDER_BY(success_rate.ASC())

result = Broker.CALCULATE(
    num_distinct_customers=COUNT(
        Customers.WHERE(
            ENDSWITH(email, '.com')
            & HAS(
                transactions_made.WHERE(
                    ISIN(ticker.symbol, ('AMZN', 'AAPL', 'GOOGL', 'META', 'NFLX'))
                )
            )
        )
    )
)

active_customers_by_country = Customers.WHERE(
    join_date >= DATETIME("2023-01-01")
).PARTITION(name="countries", by=country).CALCULATE(
    country=country,
    tac_count=COUNT(Customers)
)

result = Broker.CALCULATE(
    num_matching_customers=COUNT(
        Customers.WHERE(
            (STARTSWITH(LOWER(name), 'j') | ENDSWITH(LOWER(name), 'ez')) &
            ENDSWITH(LOWER(state), 'a')
        )
    )
)

customer_ids_with_buy_transactions = Customers.WHERE(
    HAS(transactions_made.WHERE(transaction_type == 'buy')) == 1
).CALCULATE(
    customer_id=_id
)

result = DailyPrices.WHERE(
    date >= "2023-04-01"
).PARTITION(name="distinct_tickers", by=ticker_id).CALCULATE(
    ticker_id=ticker_id
)

lowest_vti_close = DailyPrices.WHERE(
    (ticker.symbol == "VTI") & 
    (DATEDIFF("days", date, DATETIME("now")) <= 7)
).CALCULATE(
    lowest_close=MIN(close)
)

result = Broker.CALCULATE(
    total_transactions_recent_users=COUNT(
        Customers.WHERE(DATEDIFF("days", join_date, 'now') <= 70).transactions_made
    )
)

customer_time_to_first_transaction = Customers.WHERE(
    HAS(transactions_made) == 1
).CALCULATE(
    customer_id=_id,
    first_transaction_date=MIN(transactions_made.date_time)
).CALCULATE(
    customer_id=customer_id,
    time_to_first_transaction=DATEDIFF("days", join_date, first_transaction_date)
)

result = Dealership.CALCULATE(
    asp_q1_2023 = AVG(Sales.WHERE(
        (YEAR(sale_date) == 2023) & 
        (MONTH(sale_date) <= 3)
    ).sale_price)
)

result = Dealership.CALCULATE(
    total_sales_count=COUNT(Sales.WHERE(DATEDIFF("days", sale_date, DATETIME('now')) <= 6))
)

customer_ids_with_purchases = Customers.WHERE(HAS(car_purchases) == 1).CALCULATE(
    customer_id=_id
)

result = Salespersons.WHERE(
    HAS(sales_made.payment.WHERE(payment_method == "cash")) == 1
).CALCULATE(salesperson_id=_id)

result = Salespersons.WHERE(
    HAS(sales_made.WHERE(
        DATEDIFF("days", sale_date, DATETIME('now')) <= 90
    )) == 1
).CALCULATE(
    first_name=first_name,
    last_name=last_name,
    total_sales=COUNT(sales_made.WHERE(
        DATEDIFF("days", sale_date, DATETIME('now')) <= 90
    )),
    total_revenue=SUM(sales_made.WHERE(
        DATEDIFF("days", sale_date, DATETIME('now')) <= 90
    ).sale_price)
).TOP_K(3, by=total_revenue.DESC())

result = Dealership.CALCULATE(
    weekend_utility_payments=COUNT(
        PaymentsMade.WHERE(
            (vendor_name == "Utility Company") & 
            ((DAYOFWEEK(payment_date) == 1) | (DAYOFWEEK(payment_date) == 7))
        )
    )
)

result = DermTreatment.CALCULATE(
    num_patients_with_specific_emails=COUNT(Patients.WHERE(
        ENDSWITH(email, "@gmail.com") | ENDSWITH(email, "@yahoo.com")
    ))
)

result = DermTreatment.CALCULATE(
    patient_count = COUNT(Patients.WHERE(
        HAS(treatments_received.WHERE(
            (diagnosis.diag_name == 'Psoriasis vulgaris') & 
            (drug.drug_type == 'Biologic')
        )) == 1
    ))
)

average_weight_drugalin_patients = DermTreatment.CALCULATE(
    avg_weight=AVG(
        Drugs.WHERE(drug_name == 'Drugalin').treatments_used_in.patient.weight_kg
    )
)

result = DermTreatment.CALCULATE(
    CAW=AVG(Patients.WHERE(gender == "Male").weight_kg)
)

result = DermTreatment.CALCULATE(
    d7d100pir = (
        AVG(Treatments.outcome_records.WHERE(
            (day7_pasi_score != None) & (day100_pasi_score != None)
        ).day100_pasi_score) - 
        AVG(Treatments.outcome_records.WHERE(
            (day7_pasi_score != None) & (day100_pasi_score != None)
        ).day7_pasi_score)
    ) / AVG(Treatments.outcome_records.WHERE(
        (day7_pasi_score != None) & (day100_pasi_score != None)
    ).day7_pasi_score) * 100
)

result = DermTreatment.CALCULATE(
    pic_female_patients=COUNT(
        Patients.WHERE(
            (gender == "Female") & (ins_type == "Private")
        )
    )
)

result = Doctors.WHERE(
    HAS(prescribed_treatments.WHERE(drug.drug_type == "Biologic")) == 1
).PARTITION(name="doctor_states", by=loc_state).CALCULATE(
    state_name=loc_state
)

result = DermTreatment.CALCULATE(
    average_patient_age=ROUND(
        AVG(
            Patients.WHERE(
                (gender == "Male") & (ins_type == "Private")
            ).CALCULATE(
                age_in_years=DATEDIFF("years", date_of_birth, DATETIME('now'))
            ).age_in_years
        ), 0
    )
)

result = Users.CALCULATE(
    user_id=uid,
    marketing_opt_in=setting_snapshots.WHERE(
        RANKING(by=snapshot_date.DESC(), per="Users") == 1
    ).SINGULAR().marketing_opt_in
)

total_user_transactions = Users.WHERE(
    user_type != 'merchant'
).CALCULATE(
    user_id=uid,
    total_transaction_count=COUNT(transactions_sent)
)

result = Users.WHERE(HAS(sessions) == 1).CALCULATE(
    user_id=uid,
    total_duration_seconds=SUM(
        sessions.WHERE(
            (session_start_ts >= "2023-06-01") & 
            (session_start_ts < "2023-06-08")
        ).CALCULATE(
            duration_seconds=DATEDIFF("seconds", session_start_ts, session_end_ts)
        ).duration_seconds
    )
).ORDER_BY(total_duration_seconds.DESC())

result = Ewallet.CALCULATE(
    total_user_sessions=COUNT(
        UserSessions.WHERE(
            DATEDIFF("days", session_start_ts, DATETIME('now')) <= 30
        )
    )
)

us_users_unread_promotions = Users.WHERE(
    LOWER(country) == 'us'
).CALCULATE(
    user_name=username,
    total_unread_promotional_notifications=COUNT(
        notifications.WHERE(
            (notification_type == 'promotional') & (status == 'unread')
        )
    )
).WHERE(total_unread_promotional_notifications > 0)

merchant_ids_received_money = Merchants.WHERE(
    HAS(transactions_received) == 1
).CALCULATE(
    merchant_id=mid
)

result = Users.WHERE(
    HAS(notifications.WHERE(notification_type == "transaction")) == 1
).CALCULATE(
    user_id=uid
)

result = Merchants.WHERE(
    HAS(transactions_received.WHERE(
        (receiver_type == 1) & 
        (DATEDIFF("days", created_at, DATETIME('now')) <= 150)
    )) == 1
).CALCULATE(
    merchant_name=name,
    total_transactions=COUNT(transactions_received.WHERE(
        (receiver_type == 1) & 
        (DATEDIFF("days", created_at, DATETIME('now')) <= 150)
    )),
    total_amount=SUM(transactions_received.WHERE(
        (receiver_type == 1) & 
        (DATEDIFF("days", created_at, DATETIME('now')) <= 150)
    ).amount)
).TOP_K(2, by=total_amount.DESC())

result = Ewallet.CALCULATE(
    median_balance=MEDIAN(
        Merchants.WHERE(
            (status == "active") & 
            (CONTAINS(category, "retail"))
        ).balances.WHERE(
            DATEDIFF("days", updated_at, DATETIME("now")) == 0
        ).balance
    )
)

session_duration_info = UserSessions.CALCULATE(
    session_duration_seconds=DATEDIFF("seconds", session_start_ts, session_end_ts),
    device_type=device_type
)
average_session_duration_by_device = session_duration_info.PARTITION(
    name="device_groups", by=device_type
).CALCULATE(
    device_type=device_type,
    average_duration_seconds=AVG(session_duration_info.session_duration_seconds)
)

users_without_first_year_notifications = Users.WHERE(
    HASNOT(notifications.WHERE(
        DATEDIFF("days", created_at, notifications.created_at) <= 365
    )) == 1
).CALCULATE(
    username=username,
    email=email,
    signup_date=created_at
)
